"""Content of DARK_SECTOR_SYMBOLS (Markdown + LaTeX): every symbol used in the analysis of dirac16complex as dark matter and dark
energy (section 24 of 7+1.nb), with its definition and its Mathematica name.  Self-contained: every equation needed to define a symbol
is written here."""
from docgen import Doc
from doc_common import signature_block

W4 = [0.17, 0.21, 0.34, 0.28]
HEAD4 = ['symbol', 'Mathematica', 'definition', 'meaning']


def build(D, today):
    d = Doc('dirac16complex as dark matter and dark energy: symbols and their definitions',
            'A dictionary of every symbol used in the analysis of section 24 of the notebook 7+1.nb, which rests on the solutions of the '
            'coupled field equations in the three gravity regimes',
            ['Repository: github.com/once-ere/7plus1 — prepared for Nash',
             'Notebook: 7+1.nb (Wolfram Language 15.0.1)',
             'Document generated by tools/make_docs.py on ' + today],
            'For each symbol this dictionary gives the mathematical notation, the name used in the Mathematica notebook 7+1.nb (where '
            'there is one; the names of section 24 begin with `dk`), the defining equation and its meaning, grouped by topic. Longer '
            'defining equations follow each table as numbered displayed formulas. Every equation needed to define a symbol is written in this '
            'document.')

    d.h1('1. Conventions')
    d.ul(['Units: $\\hbar=c=1$; energies, masses and temperatures in GeV unless stated; cross sections in cm$^2$, lifetimes in s; $\\hbar c=1.973269804\\times10^{-14}$ GeV cm, '
          '$\\hbar=6.582119569\\times10^{-25}$ GeV s, 1 GeV $=1.78266192\\times10^{-24}$ g. The uniform Kohn–Sham matter of section 8 below uses units $m=1$.',
          'Coordinates $X=(x_0,x_1,\\dots,x_7)$: $x_0$ is time (the direction of the octonion unit $e_0=1$), $x_1,x_2,x_3$ ordinary space, '
          '$x_4,\\dots,x_7$ the four auxiliary space-like coordinates; on the world brane $x=(x_0,x_1,x_2,x_3)$, and $y=(x_4,\\dots,x_7)$.',
          'A prime is $d/dx_0$; $\\tau$ is the time since the singularity; $t$ the cosmic time of the brane; "ln" the natural logarithm.',
          'Status labels: DERIVED (an exact consequence of the field equations, checked), ESTIMATE (order of magnitude, assumptions stated), '
          'OPEN (not decided by the model).'])
    signature_block(d, eta=r'\eta', eta71=r'\eta_{71}', gam=r'\Gamma')

    d.h1('2. The model')
    d.table(HEAD4, [
        ['$\\psi$, $\\bar\\psi$', '`dirac16complex`', '$\\bar\\psi=\\psi^\\dagger\\Gamma_0$', 'the 16-component complex field and its Dirac conjugate'],
        ['$\\Gamma_A$, $\\Gamma^A$, $\\Gamma^\\mu$', '`Γ17[A]`, `Γ17up[A]`', '(2.1)', 'real 16×16 Dirac matrices; frame matrices'],
        ['$\\Omega_\\mu$', '—', '(2.1)', 'spin connection'],
        ['$m$', '`mDM` (symbolic, section 24.2)', '', 'mass of dirac16complex (free)'],
        ['$g_r$, $\\Theta^K$, $\\eta_K$', '`gg[r]`', '(2.2)', 'the nine self-couplings; Clifford products; their signs'],
        ['$\\alpha_k$, $\\Lambda$, $\\kappa$', '`alf[k]`, `lamb`, `kapS`', '$\\alpha_0=2\\Lambda$, $\\alpha_1=1$, $\\kappa=8\\pi G_8=M_8^{-6}$', 'Lovelock couplings, bulk cosmological constant'],
        ['$L_2$, $L_3$', '—', '(2.3)', 'Gauss–Bonnet and cubic Lovelock densities'],
        ['$U(b)$, $U_0$, $K_U$, $b_0$', '`uPot`, `u0B`, `kU`', '(2.4)', 'stabilizing potential of the auxiliary space'],
        ['$W=\\lbrace y=0\\rbrace$, $h$', '—', '$h_{\\mu\\nu}=g_{\\mu\\nu}(x,0)$', 'world brane and its induced metric'],
        ['$f_W$', '`fWb`', '', 'brane tension'],
        ['$\\mathcal L_{\\rm SM}$, $\\Phi$, $\\tilde\\Phi$', '—', '$\\tilde\\Phi=i\\sigma_2\\Phi^*$', 'Standard Model Lagrangian on the brane, Higgs doublet'],
        ['$y_{is}$, $G_P^f$, $\\lambda_P$', '—', '(2.5)', 'Yukawa (neutrino), vector and Higgs portals'],
        ['$L_i$, $\\psi_s$, $f$', '—', '', 'lepton doublets; brane-right-handed parts of $\\psi$ at the brane; Standard Model fermions'],
    ], widths=W4)
    d.align([r'\Gamma_A\Gamma_B+\Gamma_B\Gamma_A&=2\eta_{AB}1_{16},\quad \Gamma^A=\eta^{AA}\Gamma_A,\quad \Gamma^\mu=e_A{}^\mu\Gamma^A,&&(2.1)',
             r'\Omega_\mu&=\tfrac14\eta_{AC}\omega_\mu{}^C{}_B\Gamma^A\Gamma^B,\quad g_{\mu\nu}=\eta_{AB}e^A{}_\mu e^B{}_\nu,',
             r'\Theta^K&=i^{\sigma_r}\Gamma^{A_1}\cdots\Gamma^{A_r},\quad K=(A_1<\dots<A_r),&&(2.2)',
             r'\sigma_r&=\tfrac{r(r-1)}2\bmod2,\quad \eta_K=\eta_{A_1A_1}\cdots\eta_{A_rA_r},',
             r'L_2&=R^2-4R_{\mu\nu}R^{\mu\nu}+R_{\mu\nu\rho\sigma}R^{\mu\nu\rho\sigma},&&(2.3)',
             r'L_3&=\tfrac18\delta^{\alpha_1\beta_1\alpha_2\beta_2\alpha_3\beta_3}_{\gamma_1\delta_1\gamma_2\delta_2\gamma_3\delta_3}'
             r'R^{\gamma_1\delta_1}{}_{\alpha_1\beta_1}R^{\gamma_2\delta_2}{}_{\alpha_2\beta_2}R^{\gamma_3\delta_3}{}_{\alpha_3\beta_3},',
             r'U(b)&=U_0+\tfrac{K_U}2\ln^2(b/b_0),\qquad b^8=\det(-g_{kl}),\ k,l=4,\dots,7,&&(2.4)',
             r'S_P&=\int_Wd^4x\sqrt{|h|}\Big[-\sum_{i,s}y_{is}\bar L_i\tilde\Phi P_R\psi_s+\text{h.c.}&&(2.5)',
             r'&\qquad-G_P^f(\bar\psi\Gamma^\mu\psi)(\bar f\gamma_\mu f)-\lambda_P\Phi^\dagger\Phi\,\bar\psi\psi\Big].'])

    d.h1('3. Cosmology of the three regimes')
    d.table(HEAD4, [
        ['$a$, $b$', '`a3`, `b4`; `aS`, `bS` (symbols)', '(3.1)', 'scale factors of ordinary and auxiliary space'],
        ['$H_a$, $H_b$', '`Ha`, `Hb`', '$a\'/a$, $b\'/b$', 'Hubble rates'],
        ['$\\beta$, $m_r$, $\\phi$', '`betR`, `rIIm`', '$\\ln(b/b_0)$; $m_r^2=\\kappa K_U/12$; $\\sqrt{12}M_{\\rm Pl}\\beta$', 'radion, its mass, canonical radion'],
        ['$\\varepsilon$, $p_a$, $p_b$', '`feStress[W]`', '(3.2)', 'energy density and pressures in ordinary and auxiliary space'],
        ['$W(a,b)$', '`wW`', '(3.2)', 'comoving energy of a source at fixed occupation numbers'],
        ['$\\omega$, $k_a$, $k_b$', '`kaP`, `kbP`', '(3.3)', 'comoving energy and momenta of one particle'],
        ['$V_\\perp$, $G_4$, $\\Lambda_4$, $M_{\\rm Pl}$', '`rIIVp`, `rIIMPl`', '(3.4)', 'volume of the auxiliary torus; four-dimensional constants'],
        ['$\\rho_4$, $\\rho_{\\rm DM}$', '—', '$\\rho_4=V_\\perp\\varepsilon$', 'energy per brane volume; that of the dark matter'],
        ['$\\delta\\beta$', '`dkDbeta`', '(3.5)', 'radion displacement by the dark matter today'],
        ['$h_*$, $p$, $w_a$, $w_b$', '`rIhStar`', '(3.6)', 'matter-dominated cubic regime; equation-of-state ratios'],
        ['$P$, $Q$, $\\mathcal C$', '`rIfl`', '(3.7)', 'Einstein power laws with a fluid'],
        ['$A$, $\\vartheta$, $\\tau_E$, $H_E$', '`rIIaF`, `rIIphF`, `rIItEF`', '$\\beta\\approx A\\sin(m_r\\tau+\\vartheta)/(m_r(\\tau-\\tau_E))$, $H_E=H_a+2H_b$', 'radion oscillation after capture'],
        ['$f$', '`dkF` $=$ `rIIfrVals[[2]]`', '', 'share of the dirac16complex gas in the energy after capture'],
        ['$H_0$, $\\Omega_r$, $\\Omega_m$, $\\Omega_b$, $\\Omega_c$, $\\Omega_\\Lambda$', '`rIIH0g`, `rIIOr`, `rIIOm`, `dkOc`, `rIIOL`', '(3.8)', 'Hubble constant and density fractions today'],
        ['$h$', '`dkh`', '$H_0=100h$ km/s/Mpc', 'reduced Hubble constant (0.674)'],
        ['$H_\\infty$', '`rIIIH`', '$H_0\\Omega_\\Lambda^{1/2}$', 'final de Sitter rate'],
        ['$t_0$', '`dkAge`', '13.79 Gyr', 'age of the universe'],
    ], widths=W4)
    d.align([r'ds^2&=dx_0^2-a^2(dx_1^2+dx_2^2+dx_3^2)-b^2(dx_4^2+\cdots+dx_7^2),&&(3.1)',
             r'\varepsilon&=\frac W{a^3b^4},\qquad p_a=-\frac{\partial_aW}{3a^2b^4},\qquad p_b=-\frac{\partial_bW}{4a^3b^3},\qquad \varepsilon^{\prime}+3H_a(\varepsilon+p_a)+4H_b(\varepsilon+p_b)=0,&&(3.2)',
             r'\omega&=\sqrt{m^2+k_a^2/a^2+k_b^2/b^2},&&(3.3)',
             r'V_\perp&=b_0^4L_c^4,\qquad 8\pi G_4=\frac\kappa{V_\perp}=\frac1{M_{\rm Pl}^2},\qquad \Lambda_4=\Lambda+\kappa U_0+\frac{\kappa f_W}{V_\perp},\qquad 3H_a^2=8\pi G_4\rho_4+\Lambda_4,&&(3.4)',
             r'\beta^{\prime\prime}&+3H_a\beta^{\prime}+4\beta^{\prime2}=\kappa\Big(\frac\varepsilon6-\frac{p_a}2+\frac{p_b}3\Big)+\frac\Lambda3,\qquad \delta\beta=\frac{\kappa\varepsilon}{6m_r^2}=\frac{H_0^2\Omega_c}{2m_r^2},&&(3.5)',
             r'h_*&=-\sqrt{\alpha_2/(54\alpha_3)},\qquad a\propto\tau^p,\quad p=\frac1{1+w_a},\qquad p_a=w_a\varepsilon,\quad p_b=w_b\varepsilon,&&(3.6)',
             r'3P(1+w_a)&+4Q(1+w_b)=2,\qquad 3(P^2+4PQ+2Q^2)=\mathcal C,\qquad a\propto\tau^P,\ b\propto\tau^Q,&&(3.7)',
             r'H_a&=H_0\sqrt{\Omega_ra^{-4}+\Omega_ma^{-3}+\Omega_\Lambda},\qquad \Omega_m=\Omega_b+\Omega_c,\qquad \Omega_c=\frac{\Omega_ch^2}{h^2}.&&(3.8)'])

    d.h1('4. Kaluza–Klein modes of the auxiliary torus')
    d.table(HEAD4, [
        ['$\\vec n$, $\\vec q$', '—', '$\\vec q=2\\pi\\vec n/L_c$, $\\vec n\\in\\mathbb Z^4$', 'Kaluza–Klein momentum'],
        ['$\\ell_\\perp$', '`dkLp`', '$V_\\perp^{1/4}$', 'size of the auxiliary torus'],
        ['$\\mu_n$, $M_n$', '`rIImuK`', '(4.1)', 'Kaluza–Klein mass and mass of a level'],
        ['$r_4(k)$, $\\sigma(k)$', '`rIIr4`, `rIIsig`', '(4.2)', 'number of $\\vec n$ with $|\\vec n|^2=k$; divisor sum'],
        ['$N(\\mu)$, $dN$', '—', '(4.3)', 'number and density of levels'],
        ['$\\chi$, $\\chi_n$', '—', '$\\psi(x,y)=\\sum_n\\chi_n(x)e^{i\\vec q_n\\cdot\\vec y}/\\sqrt{V_\\perp}$', 'four-dimensional fields of the levels (four brane Dirac spinors each); $\\chi=\\chi_0$ the lightest mode'],
        ['$g$', '—', '16', 'internal states of the lightest mode (four spinors × two spins × particle, antiparticle)'],
    ], widths=W4)
    d.align([r'\mu_n&=\frac{2\pi|\vec n|}{\ell_\perp},\qquad M_n=\sqrt{m^2+\mu_n^2},&&(4.1)',
             r'r_4(k)&=8\sigma(k)-32\sigma(k/4),\qquad \sigma(k)=\sum_{d\mid k}d,\qquad \sigma(k/4)=0\ \text{unless}\ 4\mid k,&&(4.2)',
             r'N(\mu)&=\frac{V_\perp\mu^4}{32\pi^2},\qquad dN=\frac{V_\perp\mu^3d\mu}{8\pi^2}\qquad\text{(continuum limit)}.&&(4.3)'])

    d.h1('5. Observational quantities')
    d.table(HEAD4, [
        ['$Y$', '—', '$n/s$', 'comoving number density (number per entropy)'],
        ['$mY$', '`dkYm`', '(5.1)', 'required mass per entropy of the dark matter'],
        ['$\\rho_c$, $s_0$, $g_{*s0}$, $T_{\\rm CMB}$', '`dkRhoc`, `dks0`, `dkGs0`, `rIITcmb`', '(5.1)', 'critical density, entropy density today and its degrees of freedom, CMB temperature'],
        ['$M_D$, $R$, $n$', '`dkMD`; `rRS`', '(5.2)', 'Planck scale and radius in the convention of the Particle Data Group'],
        ['$\\sigma_{\\rm SI}$', '`dkSigSI[c_P, m]`', '(6.2)', 'spin-independent dark matter–nucleon cross section'],
        ['$\\sigma/m$', '`dkSigM[c_r, m]`', '(6.3)', 'self-interaction cross section per mass'],
        ['$w_0$, $w_a$', '—', '$w(a)=w_0+w_a(1-a)$', 'parameters of evolving dark energy (DESI)'],
        ['$m_{\\rm WDM}$', '—', '', 'mass of a thermal-relic warm dark-matter particle (Lyman-$\\alpha$ bound)'],
        ['Pauli bound', '`dkPauli`', '$0.13\\,\\text{keV}\\,(2/g)^{1/4}$', 'phase-space bound on fermionic dark matter'],
    ], widths=W4)
    d.align([r'mY&=\frac{\Omega_ch^2\,(\rho_c/h^2)}{s_0},\qquad \frac{\rho_c}{h^2}=3\Big(100\,\frac{\rm km}{\rm s\,Mpc}\Big)^2M_{\rm Pl}^2,\qquad s_0=\frac{2\pi^2}{45}g_{*s0}T_{\rm CMB}^3,\qquad g_{*s0}=2+\frac{21}4\cdot\frac4{11},&&(5.1)',
             r'M_{\rm Pl}^2&=R^nM_D^{n+2},\quad V_\perp=(2\pi R)^n\ (n=4)\quad\Rightarrow\quad M_D=(2\pi)^{2/3}M_8.&&(5.2)'])

    d.h1('6. The lightest mode: couplings, detection, stability')
    d.table(HEAD4, [
        ['$c_P$, $c_y$, $c_V$, $c_r$', '`cPS`, `cyS`, `cVS`, `crS`', '(6.1)', 'dimensionless couplings in units of $M_8$ (natural size: 1)'],
        ['$\\lambda_{\\rm eff}$, $y_{\\rm eff}$, $G_{\\rm eff}$, $G_r$', '`dkLam`, `dkYeff`, —, `dkGr`', '(6.1)', 'four-dimensional couplings of a level'],
        ['$v$, $m_h$, $G_F$, $\\alpha$', '`vEW`, `mHb`, `gFermi`', '$v=(\\sqrt2G_F)^{-1/2}$', 'Higgs vacuum value, Higgs mass, Fermi constant, fine-structure constant'],
        ['$f_N$, $m_N$, $\\mu$', '—', '0.30, 0.9383 GeV, $mm_N/(m+m_N)$', 'Higgs–nucleon coupling factor, nucleon mass, reduced mass'],
        ['$G_{\\chi N}$', '—', '$\\lambda_{\\rm eff}f_Nm_N/m_h^2$', 'contact coupling of $\\chi$ to nucleons'],
        ['$\\mu_P$, $\\theta$', '`dkMuP[c_y]`', '$\\mu_P=y_{\\rm eff}v/\\sqrt2$, $\\theta=\\mu_P/m$', 'portal Dirac mass; neutrino mixing angle'],
        ['$\\Gamma(\\chi\\to\\nu\\gamma)$, $\\Gamma(\\chi\\to3\\nu)$', '`dkTauG`, `dkTau3` (lifetimes)', '(6.4)', 'decay rates through the Yukawa portal'],
        ['$K$', '`dkK`', '$\\tau(\\chi\\to3\\nu)\\,c_y^2m^3$', 'lifetime constant (s GeV$^3$)'],
        ['$m_{\\max}$', '`dkMmax`', '$(K/(c_y^2t_0))^{1/3}$', 'largest mass that outlives the universe ($c_y=1$)'],
    ], widths=W4)
    d.align([r'\lambda_P&=\frac{c_P}{M_8^5},\quad y=\frac{c_y}{M_8^2},\quad G_P=\frac{c_V}{M_8^6},\quad g_r=\frac{c_r}{M_8^6};&&(6.1)',
             r'\lambda_{\rm eff}&=\frac{c_PM_8}{M_{\rm Pl}^2},\quad y_{\rm eff}=\frac{c_yM_8}{M_{\rm Pl}},\quad G_{\rm eff}=\frac{c_V}{M_{\rm Pl}^2},\quad G_r=\frac{c_r}{M_{\rm Pl}^2},',
             r'\sigma_{\rm SI}&=\frac{\lambda_{\rm eff}^2f_N^2m_N^2\mu^2}{\pi m_h^4},&&(6.2)',
             r'\sigma&\approx\frac{G_r^2m^2}{4\pi},&&(6.3)',
             r'\Gamma(\chi\to\nu\gamma)&=\frac{9\alpha G_F^2m^5\sin^22\theta}{1024\pi^4},\qquad \Gamma(\chi\to3\nu)=\frac{G_F^2m^5\theta^2}{96\pi^3},&&(6.4)',
             r'\frac{\Gamma(\chi\to\nu\gamma)}{\Gamma(\chi\to3\nu)}&=\frac{27\alpha}{8\pi}.'])

    d.h1('7. The abundance')
    d.table(HEAD4, [
        ['$O$', '`dkOver[T_RH]`', '(7.1)', 'overabundance of the primordial gas over the dark matter'],
        ['$T_{\\rm RH}$', '`trh`', '', 'reheating temperature of the brane'],
        ['$g_*$, $g_{*s}$', '`rIIgstars`', '$\\rho_{\\rm rad}=\\frac{\\pi^2}{30}g_*T^4$, $s=\\frac{2\\pi^2}{45}g_{*s}T^3$', 'relativistic degrees of freedom'],
        ['$\\Gamma_{\\rm brane}$, $\\Gamma_{\\rm bulk}$, $\\Gamma_n$', '`rIIgam`, `rIIgBulk`', '(7.2)', 'radion decay rates into brane fields and into Kaluza–Klein pairs'],
        ['$b_{\\rm QCD}$, $\\alpha_s$, $N_c$', '—', '$11-\\frac23n_f$', 'QCD beta-function coefficient, strong coupling, colours'],
        ['$B(x,y)$', '`Beta`', '$\\Gamma(x)\\Gamma(y)/\\Gamma(x+y)$', 'Euler beta function'],
        ['$T_*$', '`dkTstar`', '$(M_8^6/M_{\\rm Pl})^{1/5}$', 'normalcy temperature'],
        ['$S(x)$, $x_{\\rm RH}$', '`dkS[x]`', '(7.3)', 'fraction of the freeze-in yield made below $T_{\\rm RH}$; $x_{\\rm RH}=m_h/T_{\\rm RH}$'],
        ['$K_\\nu$', '`BesselK[ν, ·]`', '', 'modified Bessel function of the second kind'],
        ['$M_{\\rm Pl}^{\\rm (unreduced)}$', '1.22091\\*^19', '$\\sqrt{8\\pi}M_{\\rm Pl}$', 'unreduced Planck mass (freeze-in formula)'],
        ['$N$', '`nch`', '', 'number of decay channels (lepton flavours, brane spinors)'],
        ['$m_*$', '`dkMstar[N]`', '(7.4)', 'largest mass for which freeze-in and stability are compatible'],
        ['$Y_{\\rm tower}$, $\\rho_{\\rm tower}/s$', '`dkTowN`, `dkTowE`', '(7.5)', 'Kaluza–Klein tower made through the Yukawa portal'],
        ['$I_{hp}$, $I_{hp}^E$', '`dkIhp`, `dkIhpE`', '(7.6)', 'phase-space integrals of the Higgs-portal pairs'],
        ['$\\lambda(1,x_1,x_2)$', '—', '(7.6)', 'Källén function'],
        ['$T_V$', '`dkTV`', '$(M_8^{12}/M_{\\rm Pl})^{1/11}$', 'temperature above which pairs of gravitational strength are made efficiently'],
    ], widths=W4)
    d.align([r'O&=\frac f{1-f}\,\frac{T_{\rm RH}}{\frac43mY},\qquad \frac{\rho_{\rm DM}}{\rho_{\rm rad}}=\frac43\,\frac{mY}{T},&&(7.1)',
             r'\Gamma(\phi\to f\bar f)&=\frac{N_cm_f^2m_r}{24\pi M_{\rm Pl}^2}\Big(1-\frac{4m_f^2}{m_r^2}\Big)^{3/2},\quad \Gamma(\phi\to gg)=\frac{b_{\rm QCD}^2\alpha_s^2m_r^3}{96\pi^3M_{\rm Pl}^2},\quad '
             r'\Gamma_n=\frac{3\mu_n^2m_r}{8\pi M_{\rm Pl}^2}\Big(1-\frac{4\mu_n^2}{m_r^2}\Big)^{3/2},&&(7.2)',
             r'S(x)&=\frac2{3\pi}\int_x^\infty t^3K_1(t)\,dt,\qquad Y=\frac{135\,g_B}{8\pi^3\cdot1.66\,g_*^{3/2}}\,\frac{M_{\rm Pl}^{\rm (unreduced)}\Gamma}{m_B^2}\,S(x_{\rm RH}),&&(7.3)',
             r'm_*&=\Big(\frac{Y(c_y=1)\,K}{mY\,t_0}\Big)^{1/2},&&(7.4)',
             r'\sum_n\Big(1-\frac{\mu_n^2}{m_h^2}\Big)^2&=\frac{V_\perp m_h^4}{192\pi^2},\qquad \sum_n\mu_n\Big(1-\frac{\mu_n^2}{m_h^2}\Big)^2=\frac{V_\perp m_h^5}{315\pi^2},&&(7.5)',
             r'I_{hp}&=\iint_{u_1+u_2<1}u_1^3u_2^3\big(1-(u_1+u_2)^2\big)^{3/2}\big(1-(u_1-u_2)^2\big)^{1/2}du_1du_2,&&(7.6)',
             r'\lambda(1,x_1,x_2)&=(1-x_1-x_2)^2-4x_1x_2 .'])

